-- Generated from docs/reference-manifests/showcase_catalog-permission-catalog.json.
-- The source catalog is immutable evidence. Runtime enforcement bindings evolve separately.

ALTER TABLE app_role
  ADD COLUMN status varchar(16) NOT NULL DEFAULT 'ACTIVE'
    CHECK (status IN ('ACTIVE','RETIRED')),
  ADD COLUMN description varchar(300),
  ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now(),
  ADD COLUMN retired_at timestamptz,
  ADD COLUMN retired_reason varchar(500),
  ADD CONSTRAINT app_role_name_length_ck CHECK (char_length(trim(name)) BETWEEN 1 AND 10),
  ADD CONSTRAINT app_role_retirement_complete_ck CHECK (
    (status='ACTIVE' AND retired_at IS NULL AND retired_reason IS NULL)
    OR (status='RETIRED' AND retired_at IS NOT NULL AND nullif(trim(retired_reason),'') IS NOT NULL)
  );

CREATE UNIQUE INDEX app_role_active_name_ci_ux
  ON app_role(lower(name)) WHERE status='ACTIVE';
CREATE INDEX app_role_state_list_ix ON app_role(status,system_role DESC,name,id);

CREATE TABLE permission_client (
  client_code varchar(24) PRIMARY KEY
    CHECK (client_code IN ('PC','MINI_PROGRAM','CUSTOMER_PC','FIELD_APP')),
  source_key integer NOT NULL UNIQUE,
  label varchar(40) NOT NULL UNIQUE,
  sort_order integer NOT NULL,
  availability varchar(24) NOT NULL
    CHECK (availability IN ('ACTIVE','READINESS_BLOCKED')),
  blocking_reason varchar(300),
  CHECK (
    (availability='ACTIVE' AND blocking_reason IS NULL)
    OR (availability='READINESS_BLOCKED' AND nullif(trim(blocking_reason),'') IS NOT NULL)
  )
);


CREATE TABLE permission_catalog_node (
  catalog_key varchar(160) PRIMARY KEY,
  client_code varchar(24) NOT NULL REFERENCES permission_client(client_code),
  parent_key varchar(160) REFERENCES permission_catalog_node(catalog_key),
  node_type varchar(16) NOT NULL CHECK (node_type IN ('DOMAIN','GROUP','PAGE','ACTION')),
  origin varchar(16) NOT NULL CHECK (origin IN ('SOURCE','LOCAL')),
  label varchar(160) NOT NULL,
  source_path varchar(900),
  sort_order integer NOT NULL,
  leaf boolean NOT NULL,
  source_system varchar(40),
  source_captured_at timestamptz,
  source_manifest_sha256 char(64),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (
    (origin='SOURCE' AND source_system IS NOT NULL AND source_path IS NOT NULL
      AND source_captured_at IS NOT NULL AND source_manifest_sha256 IS NOT NULL)
    OR
    (origin='LOCAL' AND source_system IS NULL AND source_path IS NULL
      AND source_captured_at IS NULL AND source_manifest_sha256 IS NULL)
  )
);
CREATE UNIQUE INDEX permission_catalog_source_path_ux
  ON permission_catalog_node(client_code,source_path) WHERE source_path IS NOT NULL;
CREATE INDEX permission_catalog_tree_ix
  ON permission_catalog_node(client_code,parent_key,sort_order,catalog_key);
CREATE INDEX permission_catalog_search_ix ON permission_catalog_node(lower(label));

CREATE TABLE permission_catalog_binding (
  catalog_key varchar(160) PRIMARY KEY REFERENCES permission_catalog_node(catalog_key),
  permission_code varchar(100) REFERENCES permission(code),
  enforcement_state varchar(16) NOT NULL
    CHECK (enforcement_state IN ('ENFORCED','BLOCKED')),
  blocking_reason varchar(300),
  version bigint NOT NULL DEFAULT 0,
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (
    (enforcement_state='ENFORCED' AND permission_code IS NOT NULL AND blocking_reason IS NULL)
    OR
    (enforcement_state='BLOCKED' AND permission_code IS NULL
      AND nullif(trim(blocking_reason),'') IS NOT NULL)
  )
);
CREATE INDEX permission_catalog_binding_permission_ix
  ON permission_catalog_binding(permission_code) WHERE permission_code IS NOT NULL;

ON CONFLICT (catalog_key) DO NOTHING;

