SELECT catalog_key,'BLOCKED','已完成来源采集；对应页面的独立动作权限门禁尚未封板'
FROM permission_catalog_node WHERE origin='SOURCE' AND leaf
ON CONFLICT (catalog_key) DO NOTHING;

