  catalog_key,client_code,parent_key,node_type,origin,label,sort_order,leaf)
SELECT 'LOCAL:PC:CATEGORY:' || category,'PC','LOCAL:PC:ROOT','GROUP','LOCAL',
  CASE category
    WHEN 'WORKBENCH' THEN '工作台'
    WHEN 'MODULE' THEN '业务模块'
    WHEN 'BUSINESS' THEN '业务流转'
    WHEN 'DATA' THEN '数据控制'
    WHEN 'AUDIT' THEN '审计'
    WHEN 'SYSTEM' THEN '系统设置'
    WHEN 'QUALITY' THEN '质量控制'
    WHEN 'REPORT' THEN '报告控制'
    WHEN 'PERSONNEL' THEN '人员管理'
    WHEN 'FINANCE' THEN '合同财务'
    ELSE category
  END,
  dense_rank() OVER (ORDER BY category),false
FROM (SELECT DISTINCT category FROM permission) categories
ON CONFLICT (catalog_key) DO NOTHING;

  catalog_key,client_code,parent_key,node_type,origin,label,sort_order,leaf)
SELECT 'LOCAL:PC:PERMISSION:' || code,'PC','LOCAL:PC:CATEGORY:' || category,
  'ACTION','LOCAL',name,row_number() OVER (PARTITION BY category ORDER BY name,code),true
FROM permission
ON CONFLICT (catalog_key) DO NOTHING;

SELECT 'LOCAL:PC:PERMISSION:' || code,code,'ENFORCED' FROM permission
ON CONFLICT (catalog_key) DO NOTHING;

CREATE TABLE role_policy_revision (
  id uuid PRIMARY KEY,
  role_id uuid NOT NULL REFERENCES app_role(id) ON DELETE RESTRICT,
  revision_number integer NOT NULL CHECK (revision_number > 0),
  role_name varchar(120) NOT NULL,
  data_scope varchar(24) NOT NULL
    CHECK (data_scope IN ('ALL','ORGANIZATION','DEPARTMENT','PROJECT','SELF')),
  description varchar(300),
  status varchar(16) NOT NULL CHECK (status IN ('ACTIVE','RETIRED')),
  lock_version bigint NOT NULL CHECK (lock_version >= 0),
  reason_code varchar(100),
  comment varchar(500),
  created_by uuid REFERENCES app_user(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (role_id,revision_number)
);
CREATE INDEX role_policy_history_ix
  ON role_policy_revision(role_id,revision_number DESC);

CREATE TABLE role_policy_client (
  revision_id uuid NOT NULL REFERENCES role_policy_revision(id) ON DELETE RESTRICT,
  client_code varchar(24) NOT NULL REFERENCES permission_client(client_code),
  PRIMARY KEY (revision_id,client_code)
);

CREATE TABLE role_policy_catalog_grant (
  revision_id uuid NOT NULL REFERENCES role_policy_revision(id) ON DELETE RESTRICT,
  catalog_key varchar(160) NOT NULL REFERENCES permission_catalog_node(catalog_key),
  PRIMARY KEY (revision_id,catalog_key)
);
CREATE INDEX role_policy_catalog_grant_key_ix
  ON role_policy_catalog_grant(catalog_key,revision_id);

CREATE TABLE role_policy_permission_grant (
  revision_id uuid NOT NULL REFERENCES role_policy_revision(id) ON DELETE RESTRICT,
  permission_code varchar(100) NOT NULL REFERENCES permission(code),
  PRIMARY KEY (revision_id,permission_code)
);

ALTER TABLE app_role ADD COLUMN current_policy_revision_id uuid;

  id,role_id,revision_number,role_name,data_scope,description,status,lock_version)
SELECT md5(role.id::text || ':policy:1')::uuid,role.id,1,role.name,role.data_scope,
  role.description,role.status,role.version
FROM app_role role;

SELECT md5(role.id::text || ':policy:1')::uuid,'PC' FROM app_role role;

SELECT md5(role.id::text || ':policy:1')::uuid,grant_row.permission_code
FROM role_permission grant_row JOIN app_role role ON role.id=grant_row.role_id;

SELECT md5(role.id::text || ':policy:1')::uuid,binding.catalog_key
FROM role_permission grant_row
JOIN app_role role ON role.id=grant_row.role_id
JOIN permission_catalog_binding binding ON binding.permission_code=grant_row.permission_code
  AND binding.enforcement_state='ENFORCED';

UPDATE app_role
SET current_policy_revision_id=md5(id::text || ':policy:1')::uuid,
    updated_at=now();

ALTER TABLE app_role
  ALTER COLUMN current_policy_revision_id SET NOT NULL,
  ADD CONSTRAINT app_role_current_policy_fk
    FOREIGN KEY (current_policy_revision_id) REFERENCES role_policy_revision(id)
      ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED;

CREATE FUNCTION role_policy_snapshot_immutable() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'role policy snapshots are immutable';
END
$$;

CREATE TRIGGER role_policy_revision_immutable_trg
BEFORE UPDATE OR DELETE ON role_policy_revision
FOR EACH ROW EXECUTE FUNCTION role_policy_snapshot_immutable();
CREATE TRIGGER role_policy_client_immutable_trg
BEFORE UPDATE OR DELETE ON role_policy_client
FOR EACH ROW EXECUTE FUNCTION role_policy_snapshot_immutable();
CREATE TRIGGER role_policy_catalog_grant_immutable_trg
BEFORE UPDATE OR DELETE ON role_policy_catalog_grant
FOR EACH ROW EXECUTE FUNCTION role_policy_snapshot_immutable();
CREATE TRIGGER role_policy_permission_grant_immutable_trg
BEFORE UPDATE OR DELETE ON role_policy_permission_grant
FOR EACH ROW EXECUTE FUNCTION role_policy_snapshot_immutable();

  resource_type,source_system,capture_sha256,source_captured_at,record_count)
SELECT 'PERMISSION_CATALOG','showcase_catalog',
  source_manifest_sha256,min(source_captured_at),count(*)
FROM permission_catalog_node
WHERE origin='SOURCE'
GROUP BY source_manifest_sha256
ON CONFLICT DO NOTHING;
